package com.example.leavemanagement.balance.application;
import com.example.leavemanagement.audit.persistence.*; import com.example.leavemanagement.balance.persistence.*; import com.example.leavemanagement.people.persistence.*; import com.example.leavemanagement.policy.persistence.*; import com.example.leavemanagement.shared.api.DomainException; import com.example.leavemanagement.shared.security.CurrentActorProvider; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class BalanceAllocationService { private final LeaveBalanceRepository balances;private final LeaveBalanceMovementRepository movements;private final AuditEventRepository audits;private final EmployeeProfileRepository employees;private final LeaveTypeRepository types;private final CurrentActorProvider actors; public BalanceAllocationService(LeaveBalanceRepository b,LeaveBalanceMovementRepository m,AuditEventRepository a,EmployeeProfileRepository e,LeaveTypeRepository t,CurrentActorProvider c){balances=b;movements=m;audits=a;employees=e;types=t;actors=c;} private void admin(){if(!actors.require().hasRole("ADMINISTRATOR"))throw new DomainException(403,"ACCESS_DENIED","Administrator role is required");} public List<LeaveBalanceService.BalanceView> list(UUID employeeId){admin();employees.findById(employeeId).orElseThrow(()->new DomainException(404,"RESOURCE_NOT_FOUND","Employee was not found"));return balances.findAllByEmployeeIdOrderByPeriodStartAsc(employeeId).stream().map(b->new LeaveBalanceService.BalanceView(b.getId(),b.getLeaveTypeId(),types.findById(b.getLeaveTypeId()).map(LeaveTypeEntity::getName).orElse("Leave"),b.getPeriodStart(),b.getPeriodEnd(),(b.getAllocatedUnits()+b.getAdjustmentUnits())/2.0,b.getReservedUnits()/2.0,b.getConsumedUnits()/2.0,b.getAvailableUnits()/2.0,b.getVersion())).toList();} public LeaveBalanceService.BalanceView allocate(UUID employeeId,Command c,String idempotency){admin();employees.findById(employeeId).orElseThrow(()->new DomainException(404,"RESOURCE_NOT_FOUND","Employee was not found"));types.findById(c.leaveTypeId()).orElseThrow(()->new DomainException(404,"RESOURCE_NOT_FOUND","Leave type was not found"));if(c.periodEnd().isBefore(c.periodStart())||c.allocatedDays()<0||c.reason()==null||c.reason().isBlank())throw new DomainException(400,"VALIDATION_FAILED","Invalid allocation period, amount, or reason");if(idempotency!=null&&movements.existsByActorUserIdAndIdempotencyKey(actors.require().userId(),idempotency))throw new DomainException(409,"DUPLICATE_COMMAND","The allocation command was already applied");int units=units(c.allocatedDays());var b=balances.save(LeaveBalanceEntity.allocate(UUID.randomUUID(),employeeId,c.leaveTypeId(),c.periodStart(),c.periodEnd(),units,Instant.now()));movements.save(LeaveBalanceMovementEntity.administration(b.getId(),units,"ALLOCATE",c.reason(),actors.require().userId(),idempotency));audits.save(AuditEventEntity.administration(actors.require().userId(),"BALANCE_ALLOCATED","LEAVE_BALANCE",b.getId(),c.reason(),null,"{\"allocatedUnits\":"+units+"}"));return view(b);} private int units(double d){if(d<0||d*2!=Math.rint(d*2))throw new DomainException(400,"VALIDATION_FAILED","Days must be non-negative half-day units");return (int)Math.round(d*2);} private LeaveBalanceService.BalanceView view(LeaveBalanceEntity b){return new LeaveBalanceService.BalanceView(b.getId(),b.getLeaveTypeId(),types.findById(b.getLeaveTypeId()).map(LeaveTypeEntity::getName).orElse("Leave"),b.getPeriodStart(),b.getPeriodEnd(),(b.getAllocatedUnits()+b.getAdjustmentUnits())/2.0,b.getReservedUnits()/2.0,b.getConsumedUnits()/2.0,b.getAvailableUnits()/2.0,b.getVersion());} public record Command(UUID leaveTypeId,LocalDate periodStart,LocalDate periodEnd,double allocatedDays,String reason){} }
